from __future__ import annotations

from typing import Any, Dict, Iterator, Self
import warnings

import weakref

__doc__ = """
Instruction-level symbolic variables, offsets, environments, and scalars.

This module defines the symbolic objects that are manipulated before backend
lowering turns an instruction stream into concrete routine variables and code
containers. The key abstractions are:

- :class:`InstructionVariable`, representing a symbolic variable together with a
  chain of offsets into a key-mapped or symbolic storage layout.
- :class:`InstructionVariableOffset` and its subclasses, which model individual
  addressing steps.
- :class:`InstructionEnvironment`, a lightweight mapping from variable classes
  to concrete symbolic instances used while instructions are rewritten.
- :class:`InstructionScalar`, which carries scalar constants and minimal dtype
  information on the symbolic instruction layer.

The instruction layer stays deliberately backend-agnostic. It knows about
offset composition and symbolic substitution, but not about code generation
syntax. Backend builders later resolve these objects into
``LibRoutineVariable`` instances and concrete expressions.
"""

from ..keymap import Key

from .libroutinevar import LibRoutineVariable


class _Chainable:
    """Base helper for objects that carry input/output configuration links."""

    # every variable is derived as a subclass
    # every instance represents a certain entry in that class

    def __init__(
        self,
        input_config=None,
        output_config=None,
    ) -> None:
        self._inp_config = None
        self._out_config = None
        self.input_config = input_config
        self.output_config = output_config

    @property
    def config(self) -> tuple[Any, Any]:
        """Return the ``(input_config, output_config)`` pair."""
        return (self.input_config, self.output_config)

    @property
    def input_config(self):
        """access read-only attribute input_config"""
        if self._inp_config is None:
            return None
        return self._inp_config()

    @input_config.setter
    def input_config(self, target: Any) -> None:
        if target is None:
            inp_config = None
        else:
            inp_config = weakref.ref(target)
        self._inp_config = inp_config

    @property
    def output_config(self):
        """access read-only attribute output_config"""
        if self._out_config is None:
            return None
        return self._out_config()

    @output_config.setter
    def output_config(self, target: Any) -> None:
        if target is None:
            out_config = None
        else:
            out_config = weakref.ref(target)
        self._out_config = out_config

    def combine(self, other: _Chainable) -> _Chainable:
        """Combine two compatible chainables into a new config span."""
        if not _Chainable.is_compatible(self, other):
            raise ValueError("Incompatible Variables cannot be combined")
        return _Chainable(
            input_config=self.input_config, output_config=other.output_config
        )

    def __or__(self, other: _Chainable) -> _Chainable:
        return self.combine(other)

    @staticmethod
    def is_compatible(first: _Chainable, second: _Chainable) -> bool:
        """Return whether two chainables can be composed in sequence."""
        if first.output_config is not None:
            if second.input_config is not None:
                if first.output_config != second.input_config:
                    return False
        return True

    def _get_config(self, config=None):
        """Resolve an effective config or raise on incompatible input."""
        if self.input_config is None:
            return config
        if config is None:
            return self.input_config
        if config == self.input_config:
            return config
        raise ValueError("Incompatible input configurations")


class InstructionVariable(_Chainable):
    """
    The Instruction Variable represents input and output variables on the instruction level.
    Use myvariable = InstructionVariable.new(name) to create a new one and then
    myvariable(5) or myvariable("key") to refer to that variable at the location 5 or key,
    respectively.
    """

    _name = "DEFAULT"
    _offset_handle = "AUTO"
    _default_config = None
    _is_buffer = False

    def __init__(
        self,
        *offsets,
        input_config=None,
        output_config=None,
        _pure_copy=False,
    ) -> None:
        if input_config is None:
            input_config = type(self)._default_config
        if output_config is None:
            output_config = input_config
        super().__init__(
            input_config=input_config, output_config=output_config
        )
        self._offsets = []
        if _pure_copy:
            self._offsets = list(offsets)
        else:
            self.progress(*offsets)

    def __init_subclass__(
        cls, name=None, offset="AUTO", config=None, is_buffer=False
    ) -> None:
        """Configure subclass defaults for symbolic variable factories."""
        if name is None:
            name = cls.__name__
        cls._name = name
        if config is not None:
            cls._default_config = config
        cls._offset_handle = offset
        cls._is_buffer = is_buffer

    @classmethod
    def get_name(cls) -> str:
        """Return the symbolic class name used in string rendering."""
        return cls._name

    @classmethod
    def set_offset_handle(cls, offset_type="AUTO") -> None:
        """Set the default offset conversion strategy for the class."""
        cls._offset_handle = offset_type

    @classmethod
    def set_default_config(cls, config=None) -> None:
        """Set the default configuration object for new instances."""
        cls._default_config = config

    @classmethod
    def _new_bare(cls, name: str) -> type[InstructionVariable]:
        """Create an anonymous subclass with the given symbolic name."""
        if not isinstance(name, str):
            raise ValueError("Name must be a string")
        return type(name, (InstructionVariable,), {})

    @classmethod
    def set_buffer_state(cls, is_buffer=True) -> None:
        """Mark whether this instruction-variable class denotes a buffer."""
        cls._is_buffer = is_buffer

    @classmethod
    def new(
        cls, name, offset_type="AUTO", config=None, is_buffer=False
    ) -> type[InstructionVariable]:
        """
        Create a fresh symbolic variable subclass.

        :param name: Class-like symbolic name of the new variable type.
        :param offset_type: Default offset conversion strategy.
        :param config: Optional default input/output configuration.
        :param is_buffer: Whether the resulting variable class denotes a buffer.
        :returns: Newly generated ``InstructionVariable`` subclass.
        """
        newclass = cls._new_bare(name)
        newclass.set_offset_handle(offset_type)
        newclass.set_default_config(config)
        newclass.set_buffer_state(is_buffer)
        return newclass

    def __str__(self):
        offset = (
            f"({':'.join(map(str, self.plain_offsets))})"
            if self.plain_offsets
            else "O"
        )
        return f"<{self.name}@{offset}>"

    def __repr__(self):
        return str(self)
        # return f"<{self._name}>"

    def copy(self) -> Self:
        """Return a shallow symbolic copy including all offsets."""
        return type(self)(
            *self.plain_offsets,
            input_config=self.input_config,
            output_config=self.output_config,
            _pure_copy=True,
        )

    @property
    def name(self) -> str:
        """Return the symbolic variable name."""
        return self._name

    @property
    def plain_offsets(self) -> list[InstructionVariableOffset]:
        """Return the raw stored offsets without evaluation."""
        return list(self._offsets)

    @property
    def offsets(self) -> list[Any]:
        """Return the evaluated offsets for the current config chain."""
        return list(self.evaluate())

    def evaluate(self) -> Iterator[Any]:
        """Yield evaluated offsets in order."""
        current_pointer = self.input_config
        for offset in self._offsets:
            if current_pointer is not None and offset.input_config is not None:
                if current_pointer != offset.input_config:
                    raise ValueError("Found incompatible offsets")
            offset, new_pointer = offset.compute(current_pointer)
            yield offset
            current_pointer = new_pointer

    def progress(self, *offsets) -> Self:
        """
        Append offsets in-place.

        :param offsets: Raw offsets or ``InstructionVariableOffset`` objects.
        :returns: ``self`` for chaining.
        """
        for offset in offsets:
            if not isinstance(offset, InstructionVariableOffset):
                offset = self._auto_convert(offset)
            if not _Chainable.is_compatible(self, offset):
                raise ValueError("Incompatible offsets cannot be combined")
            self._offsets.append(offset)
            self.output_config = offset.output_config
        return self

    def _auto_convert(
        self, potential_offset: Any
    ) -> InstructionVariableOffset:
        """Convert a raw offset value using the class default policy."""
        if isinstance(potential_offset, InstructionVariableOffset):
            return potential_offset
        return InstructionVariableOffset.auto_convert(
            potential_offset,
            type(self)._offset_handle,
            self.output_config,
        )

    def progressed(self, *offsets) -> Self:
        """Return a copied variable with additional offsets appended."""
        return type(self)(
            *self.plain_offsets,
            input_config=self.input_config,
            output_config=self.output_config,
            _pure_copy=True,
        ).progress(*offsets)

    def merge(self, other: InstructionVariable) -> InstructionVariable:
        """Backward-compatible alias for :meth:`fuse`."""
        warnings.warn(
            "InstructionVariable.merge() is deprecated; use fuse() instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        return self.fuse(other)

    def fuse(self, other: InstructionVariable) -> InstructionVariable:
        """
        Concatenate the offset chains of two compatible instruction variables.

        :param other: Variable whose offsets should follow ``self``.
        :returns: New symbolic variable instance spanning both chains.
        """
        if not isinstance(other, InstructionVariable):
            raise TypeError("Merging partner must be an InstructionVariable")
        if not _Chainable.is_compatible(self, other):
            raise ValueError("Incompatible variables cannot be combined")
        return type(self)(
            *self.plain_offsets,
            *other.plain_offsets,
            input_config=self.input_config,
            output_config=other.output_config,
            _pure_copy=True,
        )

    def __add__(self, other: InstructionVariableOffset) -> InstructionVariable:
        if not isinstance(other, InstructionVariableOffset):
            raise TypeError("Offset must be an InstructionVariableOffset")
        return self.progressed(other)

    def __or__(self, other: InstructionVariable) -> InstructionVariable:
        return self.fuse(other)

    def __gt__(self, other):
        if not isinstance(other, self.__class__):
            raise TypeError(
                f"Cannot compare InstructionVariable {self} with {type(other)}"
            )
        if len(self.offsets) != len(other.offsets):
            raise ValueError("Incompatible offsets cannot be compared")
        for off1, off2 in zip(self.offsets, other.offsets):
            if off1 > off2:
                return True
            if off1 < off2:
                return False
        return False

    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return False
        if len(self.offsets) != len(other.offsets):
            return False
        for off1, off2 in zip(self.offsets, other.offsets):
            if off1 != off2:
                return False
        return True


class InstructionVariableOffset(_Chainable):
    """Base class for a single symbolic addressing step."""

    def __init__(self, value, input_config=None, output_config=None) -> None:
        super().__init__(
            input_config=input_config, output_config=output_config
        )
        self._value = value
        # self._fixed_value = None

    def __str__(self):
        return f"+{self._value}"

    def __repr__(self):
        return f"+{self._value}"

    @staticmethod
    def auto_convert(
        potential_offset, handle="AUTO", config=None
    ) -> InstructionVariableOffset:
        """
        Convert a raw offset value into an offset object.

        :param potential_offset: Integer, key, string, tuple, variable, or an
            already prepared offset.
        :param handle: Explicit conversion mode or ``"AUTO"``.
        :param config: Optional configuration/keymap used during conversion.
        :returns: Offset object matching ``handle``.
        """
        if isinstance(potential_offset, InstructionVariableOffset):
            return potential_offset
        match handle.upper().strip():
            case "AUTO":
                if isinstance(potential_offset, Key):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="KEY", config=config
                    )
                if isinstance(potential_offset, int):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="int", config=config
                    )
                if isinstance(potential_offset, str):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="key", config=config
                    )
                if isinstance(potential_offset, tuple):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="key", config=config
                    )
                if isinstance(potential_offset, InstructionVariable):
                    return InstructionVariableOffset.auto_convert(
                        potential_offset, handle="symbol", config=config
                    )
                raise TypeError(
                    f"Cannot interpret offset type from {potential_offset}."
                )
            case "KEY":
                return KeyOffset(potential_offset, keymap=config)
            case "SYMBOL":
                return SymbolicOffset(potential_offset, input_config=config)
            case "INT":
                return IntegerOffset(potential_offset, input_config=config)
            case _:
                raise KeyError(f"Unknown offset handle: {handle}")

    def compute(self, config):
        """Resolve the concrete offset and next config from ``config``."""
        raise NotImplementedError("Subclass must implement this method.")

    def evaluate(self, config=None):
        """Return the resolved offset value only."""
        offset, _ = self.compute(config=config)
        return offset


class KeyOffset(InstructionVariableOffset):
    """Offset that resolves by traversing a :mod:`phoenix.keymap` domain."""

    def __init__(self, key, keymap=None, out_config=None):
        if keymap is not None:
            if key not in keymap:
                raise KeyError(f"Key '{key}' not found in keymap {keymap}")
            out_config = keymap[key]
        super().__init__(
            value=key, input_config=keymap, output_config=out_config
        )

    def compute(self, config=None):
        """Resolve the key relative to the active keymap config."""
        current_pointer = self._get_config(config=config)
        assert current_pointer is not None, config
        offset, new_pointer = current_pointer.goto(self._value)
        return offset, new_pointer


class IntegerOffset(InstructionVariableOffset):
    """Offset carrying a direct integer displacement."""

    def compute(self, config=None):
        """simply get the prepared value"""
        return self._value, self.output_config


class StringOffset(InstructionVariableOffset):
    """Offset rendered as a literal string expression."""

    def __init__(self, expression, input_config=None, output_config=None):
        super().__init__(
            expression, input_config=input_config, output_config=output_config
        )

    def replace_expression(self, expression) -> None:
        """Replace the stored textual expression."""
        self._value = expression

    def compute(self, config=None):
        """stringify whatever enters"""
        # this might change once I have completely implemented RoutineVariables
        return str(self._value), self.output_config


class SymbolicOffset(InstructionVariableOffset):
    """Offset placeholder that can be substituted later during lowering."""

    def __init__(self, origin, input_config=None, output_config=None):
        super().__init__(
            None, input_config=input_config, output_config=output_config
        )
        self._origin = origin

    def substitute(self, value) -> None:
        """Substitute a concrete symbolic expression for the placeholder."""
        if not isinstance(value, str):
            value = str(value)
        self._value = value

    def compute(self, config=None):
        """stringify whatever enters"""
        # this might change once I have completely implemented RoutineVariables
        if self._value is None:
            return self._origin, self.output_config
            # return "?", self.output_config
        return self._value, self.output_config


class InstructionEnvironment:
    """Mapping from instruction-variable classes to symbolic instances."""

    def __init__(self, variables=None) -> None:
        if variables is None:
            variables = {}
        self._variables: Dict[type, InstructionVariable] = variables

    def items(self):
        """Yield ``(variable_class, variable)`` pairs."""
        yield from self._variables.items()

    def as_dict(self) -> dict[type, InstructionVariable]:
        """Return a plain dictionary copy of the environment."""
        return {key: val for key, val in self.items()}

    def copy(self, **_) -> InstructionEnvironment:
        """make a proper copy"""
        copied = type(self)()
        for key, variable in self.items():
            copied.update(key, variable.copy())
        return copied

    def deepcopy(self, memo=None, **kwargs) -> InstructionEnvironment:
        """Return a deepcopy-compatible copy of the environment."""
        if memo is None:
            memo = {}
        return self.__deepcopy__(memo=memo, **kwargs)

    def __deepcopy__(self, memo=None, **kwargs) -> InstructionEnvironment:
        """Implement :func:`copy.deepcopy` support with memo handling."""
        if memo is None:
            memo = {}
        if id(self) in memo:
            return memo[id(self)]
        copied = self.copy(**kwargs)
        memo[id(self)] = copied
        return copied

    def __str__(self):
        content_as_string = [
            f"{val}:<{src._name}*?*>" for src, val in self._variables.items()
        ]
        return f"<Env{content_as_string}>"

    def fuse(
        self, inner_environment: InstructionEnvironment
    ) -> InstructionEnvironment:
        """fuse an environment with another. Creates a new object."""
        new_environment = self.copy()
        new_environment._include(inner_environment, allow_fuse=True)
        return new_environment

    def merge(
        self, inner_environment: InstructionEnvironment
    ) -> InstructionEnvironment:
        """merge an environment with another. Creates a new object."""
        new_environment = self.copy()
        new_environment._include(inner_environment, allow_fuse=False)
        return new_environment

    def _include(
        self, inner_environment: InstructionEnvironment, allow_fuse=False
    ) -> InstructionEnvironment:
        """Include variables from another environment into ``self``."""
        for inner_key, inner_variable in inner_environment.items():
            self.update(inner_key, inner_variable, allow_fuse=allow_fuse)
        return self

    def __or__(self, other: InstructionEnvironment) -> InstructionEnvironment:
        return self.fuse(other)

    def delete(self, target_class) -> None:
        """Remove a variable class from the environment if it exists."""
        if target_class in self:
            del self._variables[target_class]

    def update(
        self, inner_target_class, inner_variable, allow_fuse=False
    ) -> InstructionEnvironment:
        """
        Insert or merge a symbolic variable.

        :param inner_target_class: Target instruction-variable class under which
            the value should be stored.
        :param inner_variable: Symbolic variable instance to register.
        :param allow_fuse: Whether an existing compatible variable may be fused
            with ``inner_variable`` instead of raising.
        :returns: ``self`` for chaining.
        """
        if not issubclass(inner_target_class, InstructionVariable):
            raise TypeError(
                f"Key must be an InstructionVariable subclass: {inner_target_class}"
            )
        # the added variable could be subject to an already registered offset.
        # in this case, extend this offset and update the target class.
        if (existing_target_class := type(inner_variable)) in self:
            if allow_fuse:
                self._variables[inner_target_class] = self._variables[
                    existing_target_class
                ].fuse(inner_variable)
                # for now, remove the old offset.
                self.delete(existing_target_class)
                return self
            raise KeyError(
                f"Variable of type {existing_target_class} already exists."
            )
        self._variables[inner_target_class] = inner_variable
        return self

    def keys(self):
        """Return the registered variable classes."""
        return self._variables.keys()

    def __getitem__(self, key):
        return self._variables[key]

    def __contains__(self, key):
        return key in self._variables


class InstructionScalar:
    """Scalar value with a small symbolic dtype model."""

    _DTYPES = {complex: "C", float: "F", int: "I"}
    _DTPORD = ["C", "F", "I"]

    def __init__(self, value: Any, dtype: str | None):
        if dtype is None:
            dtype = self.auto_dtype(value)
        if dtype is None:
            raise TypeError(
                f"Unsupported value type for value {value}: {type(value)}"
            )
        self._value = value
        if dtype not in self._DTYPES.values():
            raise TypeError(f"Unknown data type: {dtype}")
        self._dtype = dtype.upper()

    @property
    def dtype(self):
        """access read-only property dtype"""
        return self._dtype

    @property
    def value(self):
        """access read-only property value"""
        return self._value

    @classmethod
    def convert(cls, value, dtype=None, **kwargs) -> InstructionScalar:
        """Return ``value`` as an ``InstructionScalar`` instance."""
        if isinstance(value, cls):
            return value
        return cls(value, dtype=dtype, **kwargs)

    def auto_dtype(self, value) -> str | None:
        """Infer the symbolic dtype code for a plain Python scalar."""
        return type(self)._DTYPES.get(type(value), None)

    @classmethod
    def generalize(cls, *args):
        """identify the more general data type of two datatypes"""
        idx = None
        for arg in args:
            if arg is not None:
                if idx is None:
                    idx = cls._DTPORD.index(arg)
                else:
                    idx = min(cls._DTPORD.index(arg), idx)
        if idx is None:
            raise ValueError(
                "No common data type found among given arguments."
            )
        return cls._DTPORD[idx]

    @property
    def real(self):
        """access read-only property real"""
        return self.value.real

    @property
    def imag(self):
        """access read-only property imag"""
        if self.dtype == "C":
            return self.value.imag
        return None


class ScalarSubstitute(InstructionScalar):
    """
    Substitute a scalar. Used to combine e.g. real and imaginary part in a
    instruction variable while the libroutine variable are multiple.
    """

    def __init__(
        self,
        real: LibRoutineVariable = None,
        imag: LibRoutineVariable = None,
        dtype=None,
    ) -> None:
        """
        Create a scalar placeholder backed by routine variables.

        :param real: Variable representing the real component.
        :param imag: Variable representing the imaginary component.
        :param dtype: Optional symbolic dtype override.
        """
        self._substitute_real = real
        self._substitute_imag = imag
        if dtype is None:
            if imag is not None:
                dtype = "C"
            else:
                dtype = self._substitute_real.dtype[0].upper()
        super().__init__(value=None, dtype=dtype)

    @property
    def real(self):
        """access read-only property real"""
        return self._substitute_real

    @property
    def imag(self):
        """access read-only property imag"""
        return self._substitute_imag
